#ifndef PETRICK_H
#define PETRICK_H

#include "implicant.h"
#include "quine_mccluskey.h"

#include <set>
#include <vector>


class petrick
{
public:

    // A product term in Petrick's expression.
    //
    // Example:
    //
    // P1 P3 P5
    //
    // is represented as:
    //
    // {1, 3, 5}
    //
    using product = std::set<int>;


    // Petrick's complete expression is a sum
    // of products.
    //
    // Example:
    //
    // (P1 + P2)(P2 + P3)
    //
    // becomes:
    //
    // P1P2 + P1P3 + P2
    //
    using expression = std::vector<product>;


private:

    // Prime implicant chart generated by QM.
    quine_mccluskey::prime_chart chart;

    // Prime implicants generated by QM.
    const std::vector<implicant>& prime_implicants;

    // Prime implicants that are already essential.
    std::set<int> essential_primes;


public:

    // ========================================================
    // constructor
    // ========================================================

    petrick(
        const quine_mccluskey::prime_chart& chart,
        const std::vector<implicant>& prime_implicants,
        const std::set<int>& essential_primes
    );


    // ========================================================
    // main solver
    // ========================================================

    // Solve the prime implicant chart using
    // Petrick's method.
    //
    // Returns the complete set of selected
    // prime implicant indices.
    std::set<int> solve();


    // ========================================================
    // Petrick operations
    // ========================================================

    // Build the initial Petrick expression from
    // the uncovered minterms.
    //
    // Example:
    //
    // m1 -> P1 + P3
    // m2 -> P2 + P3
    //
    // produces:
    //
    // (P1 + P3)(P2 + P3)
    expression build_expression() const;


    // Multiply two Petrick expressions.
    //
    // Example:
    //
    // (A + B)(C + D)
    //
    // becomes:
    //
    // AC + AD + BC + BD
    expression multiply(
        const expression& lhs,
        const expression& rhs
    ) const;


    // Remove duplicate products.
    //
    // Example:
    //
    // AB + AC + AB
    //
    // becomes:
    //
    // AB + AC
    expression remove_duplicates(
        const expression& expr
    ) const;


    // Apply the absorption law.
    //
    // Example:
    //
    // A + AB = A
    //
    // So:
    //
    // {A, AB}
    //
    // becomes:
    //
    // {A}
    expression absorb(
        const expression& expr
    ) const;


    // Find all minimum solutions.
    //
    // The solutions are compared by:
    //
    // 1. Number of prime implicants
    // 2. Total number of literals
    //
    std::vector<product> find_minimum_products(
        const expression& expr
    ) const;


    // ========================================================
    // utility
    // ========================================================

    // Determine whether a product covers a particular
    // minterm.
    bool product_covers_minterm(
        const product& product,
        unsigned int minterm
    ) const;


    // Remove minterms already covered by essential
    // prime implicants.
    std::vector<unsigned int> get_uncovered_minterms() const;


    // Count total literals in a product.
    int literal_count(
        const product& product
    ) const;


    // Convert a Petrick expression into a readable
    // string.
    //
    // Example:
    //
    // (P0 + P1)(P1 + P2)
    //
    std::string to_string(
        const expression& expr
    ) const;
};

#endif
